using System;using BeamScheduleFormatter;
class ExcelEstimateDataTests {static void Main(){string xml="<BeamEstimate>"+new string('X',500000)+"\u00d8\u00f1</BeamEstimate>";byte[] data=new byte[240000];new Random(15).NextBytes(data);xml+="<DXF>"+Convert.ToBase64String(data)+"</DXF>";var chunks=ExcelEstimateData.Pack(xml);if(chunks.Length<2)throw new Exception("Chunk fixture did not span cells");if(ExcelEstimateData.Unpack(chunks)!=xml)throw new Exception("Workbook snapshot changed");bool rejected=false;chunks[0]="A"+chunks[0].Substring(1);try{ExcelEstimateData.Unpack(chunks);}catch{rejected=true;}if(!rejected)throw new Exception("Corruption accepted");Console.WriteLine("PASS: embedded workbook estimate compression, Unicode round-trip and checksum corruption checks.");}}
